const run=async(button,fn)=>{if(busy)return;busy=true;if(button)button.disabled=true;try{await fn()}catch(e){ui.showError(friendly(e));ui.error=friendly(e).message;if($('#firebase-auth-form'))render()}finally{busy=false;if(button?.isConnected)button.disabled=false}};
const requireVerified=()=>{if(!auth.currentUser)throw Error('Sign in to continue.');if(!auth.currentUser.emailVerified)throw Error('Verify your email before selling or ordering.')};
