const uploadPhotos=async images=>{const out=[];for(const image of images){if(image.startsWith('data:image/')){const path='product-images/'+auth.currentUser.uid+'/'+crypto.randomUUID()+'.jpg',ref=storageSdk.ref(storage,path);await storageSdk.uploadString(ref,image,'data_url',{contentType:'image/jpeg'});out.push(await storageSdk.getDownloadURL(ref))}else out.push(image)}return out};
